[ExtensionOf(formStr(RetailPeriodicDiscount))]
internal final class GUPRetailPeriodicDiscountForm_Extension
{
    private NumberSeqFormHandler numberSeqMarginId;
    private InventDimCtrl_Frm inventDimFormSetupPriceAdjustmentLine;

}

Method.Source:
public void init()
{
    next init();
    
    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        disableEmptyRGMLCheck = true;
        this.updateDesignPriceAdjustmentLineInventDim(InventDimFormDesignUpdate::Init);
        this.hideRetailControls();
        this.initGupControls();
    }
}

    NumberSeqFormHandler numberSeqOfferId()
    {
        if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
        {
            if (!numberSeqMarginId)
            {
                numberSeqMarginId = NumberSeqFormHandler::newForm(GUPParameters::numRefMarginComponentPriceAdjustmentId().NumberSequenceId,
                                                             this,
                                                             RetailPeriodicDiscount_RetailDiscountOffer_ds,
                                                             fieldnum(RetailDiscountOffer, OfferId)
                                                             );
            }

            if (!numberSeqOfferId)
            {
                numberSeqOfferId = NumberSeqFormHandler::newForm(GUPParameters::numRefOfferId().NumberSequenceId,
                                                             this,
                                                             RetailPeriodicDiscount_RetailDiscountOffer_ds,
                                                             fieldnum(RetailDiscountOffer, OfferId)
                                                             );
            }

            if (!numberSeqMixAndMatchId)
            {
                numberSeqMixAndMatchId = numberSeqFormHandler::newForm(GUPParameters::numRefMixAndMatchId().NumberSequenceId,
                                                                   this,
                                                                   RetailPeriodicDiscount_RetailDiscountMixAndMatch_ds,
                                                                   fieldNum(RetailDiscountMixAndMatch, OfferId)
                                                                   );
            }

            if (!numberSeqMultibuyId)
            {
                numberSeqMultibuyId = numberSeqFormHandler::newForm(GUPParameters::numRefMultibuyDiscountId().NumberSequenceId,
                                                                this,
                                                                RetailPeriodicDiscount_RetailDiscountMultibuy_ds,
                                                                fieldNum(RetailDiscountMultibuy, OfferId)
                                                                );
            }

            if (!numberSeqThresholdId)
            {
                numberSeqThresholdId = numberSeqFormHandler::newForm(GUPParameters::numRefThresholdDiscountId().NumberSequenceId,
                                                                this,
                                                                RetailPeriodicDiscount_RetailDiscountThreshold_ds,
                                                                fieldNum(RetailDiscountThreshold, OfferId)
                                                                );
            }
        }

        NumberSeqFormHandler numberSeqBase = next numberSeqOfferId();

        if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
        {
            if (retailPeriodicDiscount is RetailDiscountMixAndMatch)
            {
                return numberSeqMixAndMatchId;
            }
            else if (retailPeriodicDiscount is RetailDiscountMultibuy)
            {
                return numberSeqMultibuyId;
            }
            else if (retailPeriodicDiscount is RetailDiscountThreshold)
            {
                return numberSeqThresholdId;
            }
            else if (periodicDiscountType == RetailDiscountOfferTypeBase::Promotion)
            {
                return numberSeqMarginId;
            }
            else
            {
                return numberSeqOfferId;
            }
        }
        else
        {
            return numberSeqBase;
        }
    }

    public void close()
    {
        if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()) && numberSeqMarginId)
        {
            numberSeqMarginId.formMethodClose();
        }

        next close();
    }

    void updateDatePeriodView()
    {
        next updateDatePeriodView();

        if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
        {
            GUPValidationPeriod.enabled(retailPeriodicDiscount.DateValidationType == RetailDateValidationTypeBase::Advanced);
        }
    }

    public void setControlVisibility()
    {
        next setControlVisibility();

        if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
        {
            if (retailPeriodicDiscount is RetailDiscountOffer && periodicDiscountType == RetailDiscountOfferTypeBase::Promotion)
            {
                offerLineGroup.visible(false);
            }
        }
    }

public void refreshFormDatasource(GUPPricingAttributeSourceLevel _sourceLevel)
{
    switch (_sourceLevel)
    {
        case GUPPricingAttributeSourceLevel::Header:
            RetailPeriodicDiscount_ds.research(true);
            break;
        case GUPPricingAttributeSourceLevel::Line:
            RetailPeriodicDiscount_ds.research(true);
            RetailPeriodicDiscountLine_ds.research(true);
            break;
    }
}

    public void filterAddPriceAttributeGroupQuery(QueryBuildDataSource qbdsGroup, GUPPricingAttributeSourceLevel _sourceLevel)
    {
        QueryBuildDataSource qbdsComb = qbdsGroup.addDataSource(tableNum(GUPPriceComponentCodePriceAttributeGroupCombination));
        qbdsComb.addRange(fieldNum(GUPPriceComponentCodePriceAttributeGroupCombination, PriceComponentCode))
            .value(any2Str(retailPeriodicDiscount.PriceComponentCode));

        if (_sourceLevel == GUPPricingAttributeSourceLevel::Header)
        {
            qbdsComb.addLink(fieldNum(GUPPricingAttributeGroup, RecId),
                         fieldNum(GUPPriceComponentCodePriceAttributeGroupCombination, HeaderPriceAttributeGroup));
            qbdsComb.addGroupByField(fieldNum(GUPPriceComponentCodePriceAttributeGroupCombination, HeaderPriceAttributeGroup));
            qbdsGroup.addGroupByField(fieldNum(GUPPricingAttributeGroup, Name));
            qbdsGroup.addGroupByField(fieldNum(GUPPricingAttributeGroup, Description));
        }
        else
        {
            qbdsComb.addLink(fieldNum(GUPPricingAttributeGroup, RecId),
                         fieldNum(GUPPriceComponentCodePriceAttributeGroupCombination, LinePriceAttributeGroup));

            QueryBuildDataSource qbdsPriceRule = qbdsComb.addDataSource(tableNum(GUPPricingRule));
            qbdsPriceRule.addLink(fieldNum(GUPPricingRule, PriceAttributeGroup),
                              fieldNum(GUPPriceComponentCodePriceAttributeGroupCombination, HeaderPriceAttributeGroup));

            qbdsPriceRule.addRange(fieldNum(GUPPricingRule, RecId))
                     .value(any2Str(retailPeriodicDiscount.HeaderPricingRule));
        }
    }

    private void updateDesignPriceAdjustmentLineInventDim(InventDimFormDesignUpdate mode)
    {
        InventDimParm   inventDimParm       = InventDimParm::allInventDim();
        InventDimParm   inventDimParmEnable = inventDimParm.data();

        switch (mode)
        {
            case InventDimFormDesignUpdate::Init:
                if (!inventDimFormSetupPriceAdjustmentLine)
                {
                    inventDimFormSetupPriceAdjustmentLine = InventDimCtrl::newFromForm(this);
                }
                
                inventDimParm.initRetailPeriodicDiscountGroup();

                inventDimFormSetupPriceAdjustmentLine.parmDimParmEnabled(inventDimParmEnable);
                inventDimFormSetupPriceAdjustmentLine.parmDontShowDisabled(false);
                inventDimFormSetupPriceAdjustmentLine.parmDimParmVisibleGrid(inventDimParm);
                inventDimFormSetupPriceAdjustmentLine.formSetControls(true);
                break;
        }

    }

    [FormControlEventHandler(formControlStr(RetailPeriodicDiscount, RetailPeriodicDiscount_PriceComponentCode1), FormControlEventType::Lookup)]
    public static void RetailPeriodicDiscount_PriceComponentCode1_OnLookup(FormControl sender, FormControlEventArgs e)
    {
        SysReferenceTableLookup sysReferenceTableLookup;
        Query                   query = new Query();
        QueryBuildDataSource    qbds = query.addDataSource(tableNum(GUPPriceComponentCode));
        QueryBuildDataSource    qbdsComponent;

        sysReferenceTableLookup = SysReferenceTableLookup::newParameters(tableNum(GUPPriceComponentCode), sender);
        sysReferenceTableLookup.addLookupfield(fieldNum(GUPPriceComponentCode, Name));
        sysReferenceTableLookup.addLookupfield(fieldNum(GUPPriceComponentCode, Description));

        FormDataSource RetailPeriodicDiscount_ds = sender.formRun().dataSource(tableStr(RetailPeriodicDiscount));
        RetailPeriodicDiscount periodicDiscount = RetailPeriodicDiscount_ds.cursor();
        RetailDiscountOfferTypeBase periodicDiscountType = periodicDiscount.PeriodicDiscountType;

        if (periodicDiscountType == RetailDiscountOfferTypeBase::Promotion)
        {
            qbds.addRange(fieldNum(GUPPriceComponentCode, PriceComponent)).value(queryValue(GUPPriceComponent::PriceMarginComponentAdjustment));
        }
        else if (periodicDiscountType == RetailDiscountOfferTypeBase::DiscountOffer ||
                 periodicDiscountType == RetailDiscountOfferTypeBase::Multibuy      ||
                 periodicDiscountType == RetailDiscountOfferTypeBase::MixAndMatch   ||
                 periodicDiscountType == RetailDiscountOfferTypeBase::Threshold     )
        {
            qbds.addRange(fieldNum(GUPPriceComponentCode, PriceComponent)).value(queryValue(GUPPriceComponent::RetailDiscounts));
        }

        sysReferenceTableLookup.parmQuery(query);
        sysReferenceTableLookup.performFormLookup();

        FormControlCancelableSuperEventArgs ce = e as FormControlCancelableSuperEventArgs;
        ce.CancelSuperCall();
    }

private void hideRetailControlsForMarginComponentCode()
{ 
    if (periodicDiscountType == RetailDiscountOfferTypeBase::Promotion)
    {
        this.design().controlName(formControlStr(RetailPeriodicDiscount, RetailPeriodicDiscount_OfferId1)).visible(false);
        this.design().controlName(formControlStr(RetailPeriodicDiscount, RetailPeriodicDiscount_PeriodicDiscountType)).visible(false);
        this.design().controlName(formControlStr(RetailPeriodicDiscount, RetailPeriodicDiscount_PeriodicDiscountType1)).visible(false);
        this.design().controlName(formControlStr(RetailPeriodicDiscount, RetailPeriodicDiscount_DiscountPercentValue)).visible(false);
        
        Concurrency.visible(false);
        ValidationPeriod.visible(false);
        DiscountOfferTabPage.visible(false);
    }
}

    private void hideRetailControls()
    {
        this.hideRetailControlsForMarginComponentCode();
        this.design().controlName(formControlStr(RetailPeriodicDiscount, RetailPeriodicDiscount_Name)).visible(false);
        this.design().controlName(formControlStr(RetailPeriodicDiscount, RetailPeriodicDiscountCopyList)).visible(false);
        this.design().controlName(formControlStr(RetailPeriodicDiscount, RetailDiscountPriceGroupMenuItemButton)).visible(false);
        this.design().controlName(formControlStr(RetailPeriodicDiscount, ViewSharedProductsButton)).visible(false);
        this.design().controlName(formControlStr(RetailPeriodicDiscount, AllDiscountsLineButtonGroup)).visible(false);
        this.design().controlName(formControlStr(RetailPeriodicDiscount, RetailGroupMemberLineGroup)).visible(false);

        AddProducts.visible(false);
        InventoryDimension.visible(false);
        Account.visible(false);
        PeriodicDiscount_OfferLedgerDimension.visible(false);
        DiscountCode.visible(false);
        DiscountCode_IsDiscountCodeRequired.visible(false);
        MatchAllAssociatedPriceGroups.visible(false);
        PriorityGroup.visible(false);
        ModeOfDelivery.visible(false);
    }

    private void initGupControls()
    {
        this.initGupDiscountOfferControls();
        this.initGupDiscountThresholdControls();
        this.initGupDiscountMixAndMatchControls();
        this.initGupDiscountMultibuyControls();
        this.initGupMarginComponentControls();

        GUPCaclulationTabPage.visible(true);
        GUPPeriodicDiscountCopy.visible(true);
        EditHeaderPricingAttrGrp.visible(true);
        RetailPeriodicDiscount_PriceComponentCode1.visible(true);
        RetailPeriodicDiscount_PriceComponentCode1.mandatory(true);
        EditLinePricingAttrGrp.visible(true);
        RetailPeriodicDiscount_PriceComponentCode.visible(true);
        RetailPeriodicDiscount_PriceComponentType1.visible(true);
        RetailPeriodicDiscount_HeaderPricingGroupCode.visible(true);
        GUPPricingRuleHeader_PriceAttributeGroup.visible(true);
        GUPMarginComponentPriceAdjustment_LinePricingGroupDetails.visible(true);
        GUPPeriodicDiscountLineCopy.visible(true);
        InventDimParmFixedAction.visible(true);
        RetailPeriodicDiscountLine_LinePricingGroupCode.visible(true);
        RetailPeriodicDiscountLine_LinePricingGroupName.visible(true);
        RetailPeriodicDiscountLine_LinePricingGroupDetails.visible(true);
        InventoryDimensions.visible(true);
        RetailPeriodicDiscountLine_UnitAppliesToAll.visible(true);
        GUPPriceComponentCodePriceAttributeGroupSelection_Line_Priority.visible(true);

        GUPCaclulationTabPage.enabled(true);
        GUPPeriodicDiscountCopy.enabled(true);
        EditHeaderPricingAttrGrp.enabled(true);
        RetailPeriodicDiscount_PriceComponentCode1.enabled(true);
        EditLinePricingAttrGrp.enabled(true);
        RetailPeriodicDiscount_PriceComponentCode.enabled(true);
        RetailPeriodicDiscount_PriceComponentType1.enabled(true);
        RetailPeriodicDiscount_HeaderPricingGroupCode.enabled(true);
        GUPPricingRuleHeader_PriceAttributeGroup.enabled(true);
        GUPMarginComponentPriceAdjustment_LinePricingGroupDetails.enabled(true);
        GUPPeriodicDiscountLineCopy.enabled(true);
        InventDimParmFixedAction.enabled(true);
        RetailPeriodicDiscountLine_LinePricingGroupCode.enabled(true);
        RetailPeriodicDiscountLine_LinePricingGroupName.enabled(true);
        RetailPeriodicDiscountLine_LinePricingGroupDetails.enabled(true);
        InventoryDimensions.enabled(true);
        RetailPeriodicDiscountLine_UnitAppliesToAll.enabled(true);
        GUPPriceComponentCodePriceAttributeGroupSelection_Line_Priority.enabled(true);
    }

    private void initGupDiscountOfferControls()
    {
        if (periodicDiscountType == RetailDiscountOfferTypeBase::DiscountOffer)
        {
            GupDiscountOffer.visible(true);
            DiscountOffer.visible(false);

            GupDiscountOffer.enabled(true);
        }
    }

    private void initGupDiscountThresholdControls()
    {
        if (periodicDiscountType == RetailDiscountOfferTypeBase::Threshold)
        {
            GUPThresholdDiscount.visible(true);
            ThresholdDiscount.visible(false);

            GUPThresholdDiscount.enabled(true);
        }
    }

    private void initGupDiscountMixAndMatchControls()
    {
        if (periodicDiscountType == RetailDiscountOfferTypeBase::MixAndMatch)
        {
            GUPDiscountMixAndMatch.visible(true);
            MixAndMatchDiscount.visible(false);

            GUPDiscountMixAndMatch.enabled(true);
        }
    }

    private void initGupDiscountMultibuyControls()
    {
        if (periodicDiscountType == RetailDiscountOfferTypeBase::Multibuy)
        {
            GUPQuatityDiscount.visible(true);
            QuatityDiscount.visible(false);

            GUPQuatityDiscount.enabled(true);
        }      
    }

    private void initGupMarginComponentControls()
    {
        if (periodicDiscountType == RetailDiscountOfferTypeBase::Promotion)
        {
            OfferLineGroup.visible(false);
            PriceAdjustments.visible(false);

            MarginComponentPriceAdjustments.visible(true);
            GUPRetailPeriodicDiscount_OfferId1.visible(true);
            GUPValidationPeriod.visible(true);
            GUPConcurrency.visible(true);
            RetailPeriodicDiscount_PriceComponentType.visible(true);
            RetailPeriodicDiscountLine_RetailDiscountLineOffer_CalculateMethod.visible(true);
            RetailPeriodicDiscountLine_RetailDiscountLineOffer_CalculateValue.visible(true);
            GUPPriceMarginComponentSetup_CompoundcalculationBasis.visible(true);

            MarginComponentPriceAdjustments.enabled(true);
            GUPRetailPeriodicDiscount_OfferId1.enabled(true);
            GUPValidationPeriod.enabled(true);
            GUPConcurrency.enabled(true);
            RetailPeriodicDiscount_PriceComponentType.enabled(true);
            RetailPeriodicDiscountLine_RetailDiscountLineOffer_CalculateMethod.enabled(true);
            RetailPeriodicDiscountLine_RetailDiscountLineOffer_CalculateValue.enabled(true);
            GUPPriceMarginComponentSetup_CompoundcalculationBasis.enabled(true);
        }
    }

    public void setDatasourceEditability()
    {
        next setDatasourceEditability();

        if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
        {
            boolean isDiscountDisabled = !retailPeriodicDiscount.Status;

            EditLinePricingAttrGrp.enabled(isDiscountDisabled);
            GUPPeriodicDiscountLineCopy.enabled(isDiscountDisabled);
        }
    }
